package com.oasis.reservation.ui;
import com.oasis.reservation.model.User;import com.oasis.reservation.ui.api.RailToolsPanel;import com.oasis.reservation.util.Theme;import javax.swing.*;import java.awt.*;import java.util.*;
public class MainFrame extends JFrame{
 private final CardLayout cards=new CardLayout();private final JPanel content=new JPanel(cards);private final DashboardPanel dashboard;private final SavedBookingsPanel saved;private final ReservationPanel booking;private final CancellationPanel cancel;private final JLabel pageTitle=new JLabel("Dashboard");
 public MainFrame(String username){setTitle("RailReserve • Railway Reservation System");setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);setSize(1240,800);setMinimumSize(new Dimension(1050,680));setLocationRelativeTo(null);dashboard=new DashboardPanel(username);saved=new SavedBookingsPanel();booking=new ReservationPanel();cancel=new CancellationPanel();build(username);}
 public MainFrame(User u){this(u.username());}
 private void build(String username){JPanel root=new JPanel(new BorderLayout());root.setBackground(Theme.CLOUD);root.add(sidebar(username),BorderLayout.WEST);JPanel main=new JPanel(new BorderLayout());main.setOpaque(false);main.add(topbar(username),BorderLayout.NORTH);content.setOpaque(false);content.add(dashboard,"DASH");content.add(booking,"BOOK");content.add(cancel,"CANCEL");content.add(saved,"SAVED");content.add(new RailToolsPanel(),"RAIL");main.add(content,BorderLayout.CENTER);root.add(main,BorderLayout.CENTER);setContentPane(root);show("DASH","Dashboard");}
 private JPanel sidebar(String username){JPanel s=new JPanel(new BorderLayout());s.setBackground(Theme.NAVY);s.setPreferredSize(new Dimension(225,0));s.setBorder(BorderFactory.createEmptyBorder(24,14,20,14));JPanel top=new JPanel();top.setOpaque(false);top.setLayout(new BoxLayout(top,BoxLayout.Y_AXIS));JLabel logo=Theme.heading("RAILRESERVE",21);logo.setForeground(Color.WHITE);top.add(logo);top.add(Box.createVerticalStrut(3));JLabel sub=Theme.body("Railway workspace");sub.setForeground(Color.decode("#b9cfe1"));top.add(sub);top.add(Box.createVerticalStrut(30));String[][] items={{"⌂  Dashboard","DASH"},{"🎫  Book Ticket","BOOK"},{"🔎  Find / Cancel","CANCEL"},{"▣  My Bookings","SAVED"},{"🚆  Rail Information","RAIL"}};for(String[] it:items){JButton b=new JButton(it[0]);b.setHorizontalAlignment(SwingConstants.LEFT);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,44));b.setForeground(Color.decode("#eaf3fa"));b.setBackground(Theme.NAVY);b.setBorder(BorderFactory.createEmptyBorder(10,14,10,10));b.setFocusPainted(false);b.setFont(Theme.font(13,Font.BOLD));b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.addActionListener(e->show(it[1],it[0].replaceAll("^[^ ]+  ","")));top.add(b);top.add(Box.createVerticalStrut(5));}s.add(top,BorderLayout.NORTH);JPanel bottom=new JPanel();bottom.setOpaque(false);bottom.setLayout(new BoxLayout(bottom,BoxLayout.Y_AXIS));JLabel u=Theme.body("Signed in as "+username);u.setForeground(Color.decode("#b9cfe1"));bottom.add(u);bottom.add(Box.createVerticalStrut(10));JButton out=new JButton("↪  Sign out");out.setHorizontalAlignment(SwingConstants.LEFT);out.setForeground(Color.WHITE);out.setBackground(Theme.NAVY);out.setBorder(BorderFactory.createEmptyBorder(9,12,9,12));out.setFocusPainted(false);out.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});bottom.add(out);s.add(bottom,BorderLayout.SOUTH);return s;}
 private JPanel topbar(String username){JPanel p=new JPanel(new BorderLayout());p.setBackground(Theme.PAPER);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0,0,1,0,Theme.HAIRLINE),BorderFactory.createEmptyBorder(16,24,16,24)));pageTitle.setFont(Theme.font(19,Font.BOLD));pageTitle.setForeground(Theme.NAVY);p.add(pageTitle,BorderLayout.WEST);p.add(Theme.body("Java Development • Oasis Infobyte"),BorderLayout.EAST);return p;}
 private void show(String card,String title){cards.show(content,card);pageTitle.setText(title);if(card.equals("DASH"))dashboard.refresh();if(card.equals("SAVED"))saved.refresh();}
}
